package io.bluetape4k.graph.age

import com.github.benmanes.caffeine.cache.Cache
import com.github.benmanes.caffeine.cache.Caffeine
import io.bluetape4k.graph.model.BfsDfsOptions
import io.bluetape4k.graph.model.ComponentOptions
import io.bluetape4k.graph.model.CycleOptions
import io.bluetape4k.graph.model.DegreeOptions
import io.bluetape4k.graph.model.DegreeResult
import io.bluetape4k.graph.model.GraphComponent
import io.bluetape4k.graph.model.GraphCycle
import io.bluetape4k.graph.model.GraphEdge
import io.bluetape4k.graph.model.GraphElementId
import io.bluetape4k.graph.model.GraphPath
import io.bluetape4k.graph.model.GraphVertex
import io.bluetape4k.graph.model.NeighborOptions
import io.bluetape4k.graph.model.PageRankOptions
import io.bluetape4k.graph.model.PageRankScore
import io.bluetape4k.graph.model.PathOptions
import io.bluetape4k.graph.model.TraversalVisit
import io.bluetape4k.graph.repository.GraphOperations
import io.bluetape4k.logging.KLogging
import java.time.Duration

/**
 * [AgeGraphOperations] 를 감싸는 Caffeine 기반 읽기 캐시 데코레이터.
 * findVertexById, findVerticesByLabel, neighbors 3가지 hot-read 경로만 캐시한다.
 * 쓰기 작업(createVertex/createEdge/update/delete/drop)이 발생하면 전체 캐시를 무효화한다.
 *
 * Redis / Lettuce 를 사용하지 않는 pure in-memory 캐시이다.
 */
class CachingAgeGraphOperations(
    private val delegate: AgeGraphOperations,
    maxSize: Long = 10_000,
    expireAfterWrite: Duration = Duration.ofMinutes(5),
) : GraphOperations {

    companion object : KLogging()

    private data class VertexKey(val label: String, val id: GraphElementId)
    private data class LabelKey(val label: String, val filter: Map<String, Any?>)
    private data class NeighborKey(val startId: GraphElementId, val options: NeighborOptions)

    private val vertexByIdCache: Cache<VertexKey, GraphVertex> = Caffeine.newBuilder()
        .maximumSize(maxSize).expireAfterWrite(expireAfterWrite).build()
    private val verticesByLabelCache: Cache<LabelKey, List<GraphVertex>> = Caffeine.newBuilder()
        .maximumSize(maxSize).expireAfterWrite(expireAfterWrite).build()
    private val neighborsCache: Cache<NeighborKey, List<GraphVertex>> = Caffeine.newBuilder()
        .maximumSize(maxSize).expireAfterWrite(expireAfterWrite).build()

    private fun invalidateAll() {
        vertexByIdCache.invalidateAll()
        verticesByLabelCache.invalidateAll()
        neighborsCache.invalidateAll()
    }

    // -- GraphSession --
    override fun createGraph(name: String) = delegate.createGraph(name).also { invalidateAll() }
    override fun dropGraph(name: String) = delegate.dropGraph(name).also { invalidateAll() }
    override fun graphExists(name: String): Boolean = delegate.graphExists(name)
    override fun close() = delegate.close()

    // -- Vertex read paths (CACHED) --
    override fun findVertexById(label: String, id: GraphElementId): GraphVertex? {
        val key = VertexKey(label, id)
        vertexByIdCache.getIfPresent(key)?.let { return it }
        val v = delegate.findVertexById(label, id)
        if (v != null) vertexByIdCache.put(key, v)
        return v
    }

    override fun findVerticesByLabel(label: String, filter: Map<String, Any?>): List<GraphVertex> {
        val key = LabelKey(label, filter)
        verticesByLabelCache.getIfPresent(key)?.let { return it }
        val list = delegate.findVerticesByLabel(label, filter)
        verticesByLabelCache.put(key, list)
        return list
    }

    override fun neighbors(startId: GraphElementId, options: NeighborOptions): List<GraphVertex> {
        val key = NeighborKey(startId, options)
        neighborsCache.getIfPresent(key)?.let { return it }
        val list = delegate.neighbors(startId, options)
        neighborsCache.put(key, list)
        return list
    }

    // -- Vertex write paths (INVALIDATE) --
    override fun createVertex(label: String, properties: Map<String, Any?>): GraphVertex =
        delegate.createVertex(label, properties).also { invalidateAll() }

    override fun updateVertex(label: String, id: GraphElementId, properties: Map<String, Any?>): GraphVertex? =
        delegate.updateVertex(label, id, properties).also { invalidateAll() }

    override fun deleteVertex(label: String, id: GraphElementId): Boolean =
        delegate.deleteVertex(label, id).also { invalidateAll() }

    override fun countVertices(label: String): Long = delegate.countVertices(label)

    // -- Edge paths --
    override fun createEdge(fromId: GraphElementId, toId: GraphElementId, label: String, properties: Map<String, Any?>): GraphEdge =
        delegate.createEdge(fromId, toId, label, properties).also { invalidateAll() }

    override fun findEdgesByLabel(label: String, filter: Map<String, Any?>): List<GraphEdge> =
        delegate.findEdgesByLabel(label, filter)

    override fun deleteEdge(label: String, id: GraphElementId): Boolean =
        delegate.deleteEdge(label, id).also { invalidateAll() }

    // -- Traversal --
    override fun shortestPath(fromId: GraphElementId, toId: GraphElementId, options: PathOptions): GraphPath? =
        delegate.shortestPath(fromId, toId, options)

    override fun allPaths(fromId: GraphElementId, toId: GraphElementId, options: PathOptions): List<GraphPath> =
        delegate.allPaths(fromId, toId, options)

    // -- Algorithm delegation (not cached) --
    override fun degreeCentrality(vertexId: GraphElementId, options: DegreeOptions): DegreeResult =
        delegate.degreeCentrality(vertexId, options)
    override fun bfs(startId: GraphElementId, options: BfsDfsOptions): List<TraversalVisit> = delegate.bfs(startId, options)
    override fun dfs(startId: GraphElementId, options: BfsDfsOptions): List<TraversalVisit> = delegate.dfs(startId, options)
    override fun detectCycles(options: CycleOptions): List<GraphCycle> = delegate.detectCycles(options)
    override fun connectedComponents(options: ComponentOptions): List<GraphComponent> = delegate.connectedComponents(options)
    override fun pageRank(options: PageRankOptions): List<PageRankScore> = delegate.pageRank(options)
}
```

Note: the executor must verify each overridden method signature against `graph/graph-core/src/main/kotlin/io/bluetape4k/graph/repository/*.kt` (GraphSession, GraphVertexRepository, GraphEdgeRepository, GraphTraversalRepository, GraphAlgorithmRepository, GraphGenericRepository). If `GraphGenericRepository` adds methods beyond those above, add `override fun ... = delegate....(...)` pass-throughs with no caching. Do NOT use Redis/Lettuce anywhere.
